/// <summary>
/// The UIBuilder class for <c>METSendSalesOrderCancelledBusinessEventContract</c>
/// </summary>
public class METSendSalesOrderCancelledBusinessEventUIBuilder extends SysOperationAutomaticUIBuilder
{
    DialogField IndustryKey;

}

Method.Source:
/// <summary>
/// Action after build of the dialog UI.
/// </summary>
public void postBuild()
{
    super();
 
    // get references to dialog controls after creation
    IndustryKey = this.bindInfo().getDialogField(this.dataContractObject(),
                                methodStr(METSendSalesOrderCancelledBusinessEventContract, parmIndustryKey));
}

/// <summary>
/// Registers the dialog field methods to capture events,
/// and create lookup control for IndustryKey dialog field.
/// </summary>
public void postRun()
{
    super();
 
    // register overrides for form control events
    IndustryKey.registerOverrideMethod(methodstr(FormStringControl, lookup),
            methodstr(METSendSalesOrderCancelledBusinessEventUIBuilder, lookupIndustryKey), this);
}

    /// <summary>
    /// Performs the lookup for Industry key
    /// </summary>
    /// <param name = "_formStringControl">IndustryKey control</param>
    public void lookupIndustryKey(FormStringControl _formStringControl)
    {
        Query                   query = new Query();
        QueryBuildDataSource    qbds;
        SysTableLookup          sysTableLookup;        

        if (_formStringControl != null)
        {
            sysTableLookup = SysTableLookup::newParameters(tablenum(METIndustryKeyTable), _formStringControl);
            sysTableLookup.addLookupfield(fieldnum(METIndustryKeyTable, IndustryKey), true);
            sysTableLookup.addLookupfield(fieldnum(METIndustryKeyTable, IndustryChannel),false);
            
            qbds = query.addDataSource(tableNum(METIndustryKeyTable));

            sysTableLookup.parmUseLookupValue(false);
            sysTableLookup.parmQuery(query);
            sysTableLookup.performFormLookup();

        }
    }
